def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    guide_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    guide_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    bg = max(range(10), key=lambda v: sum(x == v for row in grid for x in row if v != 2))
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2, 8)]
    if not obj:
        return out
    if guide_row is not None:
        rs = [r for r, c, v in obj]
        if min(rs) > guide_row:
            dr = guide_row + 1 - min(rs)
            newline = max(r for r, c, v in obj) + dr + 1
        else:
            dr = guide_row - 1 - max(rs)
            newline = min(r for r, c, v in obj) + dr - 1
        for r, c, v in obj:
            out[r][c] = bg
        for r, c, v in obj:
            rr = r + dr
            if 0 <= rr < h:
                out[rr][c] = v
        if 0 <= newline < h:
            out[newline] = [8] * w
    elif guide_col is not None:
        cs = [c for r, c, v in obj]
        if min(cs) > guide_col:
            dc = guide_col + 1 - min(cs)
            newline = max(c for r, c, v in obj) + dc + 1
        else:
            dc = guide_col - 1 - max(cs)
            newline = min(c for r, c, v in obj) + dc - 1
        for r, c, v in obj:
            out[r][c] = bg
        for r, c, v in obj:
            cc = c + dc
            if 0 <= cc < w:
                out[r][cc] = v
        if 0 <= newline < w:
            for r in range(h):
                out[r][newline] = 8
    return out

